INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI001', 'HDSAT-RW-M33-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Epidemiology is the study and analysis of the distribution (who, when, and where), patterns and determinants of health and disease conditions in a defined population, and application of this knowledge to prevent diseases. It is a cornerstone of public health, and shapes policy decisions and evidence-based practice by identifying risk factors for disease and targets for preventive healthcare. Epidemiologists help with study design, collection, and statistical analysis of data, amend interpretation and dissemination of results (including peer review and occasional systematic review). Epidemiology has helped develop methodology used in clinical research, public health studies, and, to a lesser extent, basic research in the biological sciences. Major areas of epidemiological study include disease causation, transmission, outbreak investigation, disease surveillance, environmental epidemiology, forensic epidemiology, occupational epidemiology, screening, biomonitoring, and comparisons of treatment effects such as in clinical trials. Epidemiologists rely on other scientific disciplines like biology to better understand disease processes, statistics to make efficient use of the data and draw appropriate conclusions, social sciences to better understand proximate and distal causes, and engineering for exposure assessment.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Epidemiology focuses only on infectious diseases."}, {"id": "B", "text": "Epidemiology studies the distribution and causes of disease in populations and uses that knowledge to guide prevention and policy."}, {"id": "C", "text": "Epidemiology is unrelated to public health policy."}, {"id": "D", "text": "Epidemiology studies individual patients in hospitals only."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Epidemiology", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Epidemiology', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI001', 'B', ARRAY['B']::TEXT[], 'The passage defines epidemiology, describes its methods, and explains its role in public health.', '{"D": "The text defines it as the study of health conditions in a defined population.", "C": "The text says it shapes policy decisions and evidence-based practice.", "A": "The text lists environmental, occupational, and forensic epidemiology among its areas."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF001', 'HDSAT-RW-M33-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Epidemiology is the study and analysis of the distribution (who, when, and where), patterns and determinants of health and disease conditions in a defined population, and application of this knowledge to prevent diseases. It is a cornerstone of public health, and shapes policy decisions and evidence-based practice by identifying risk factors for disease and targets for preventive healthcare. Epidemiologists help with study design, collection, and statistical analysis of data, amend interpretation and dissemination of results (including peer review and occasional systematic review). Epidemiology has helped develop methodology used in clinical research, public health studies, and, to a lesser extent, basic research in the biological sciences. Major areas of epidemiological study include disease causation, transmission, outbreak investigation, disease surveillance, environmental epidemiology, forensic epidemiology, occupational epidemiology, screening, biomonitoring, and comparisons of treatment effects such as in clinical trials. Epidemiologists rely on other scientific disciplines like biology to better understand disease processes, statistics to make efficient use of the data and draw appropriate conclusions, social sciences to better understand proximate and distal causes, and engineering for exposure assessment.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF001', 'A', ARRAY['A']::TEXT[], 'Identifying risks and prevention targets is exactly what informs policy and practice.', '{"D": "The text says the field shapes policy decisions by identifying risk factors and prevention targets.", "B": "The text says epidemiology has helped develop clinical research methods, not replace treatment.", "C": "The text lists many areas beyond genetics."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS001', 'HDSAT-RW-M33-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Epidemiology is the study and analysis of the distribution (who, when, and where), patterns and determinants of health and disease conditions in a defined population, and application of this knowledge to prevent diseases. It is a cornerstone of public health, and shapes policy decisions and evidence-based practice by identifying risk factors for disease and targets for preventive healthcare. Epidemiologists help with study design, collection, and statistical analysis of data, amend interpretation and dissemination of results (including peer review and occasional systematic review). Epidemiology has helped develop methodology used in clinical research, public health studies, and, to a lesser extent, basic research in the biological sciences. Major areas of epidemiological study include disease causation, transmission, outbreak investigation, disease surveillance, environmental epidemiology, forensic epidemiology, occupational epidemiology, screening, biomonitoring, and comparisons of treatment effects such as in clinical trials. Epidemiologists rely on other scientific disciplines like biology to better understand disease processes, statistics to make efficient use of the data and draw appropriate conclusions, social sciences to better understand proximate and distal causes, and engineering for exposure assessment.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares epidemiology with clinical medicine."}, {"id": "B", "text": "It defines epidemiology, explains its role and methods, and lists its major areas and relied-upon disciplines."}, {"id": "C", "text": "It argues that epidemiology cannot prevent disease."}, {"id": "D", "text": "It narrates the investigation of one outbreak."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Epidemiology", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Epidemiology', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS001', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition and purpose to areas and methods.', '{"D": "No single outbreak is narrated.", "A": "Clinical medicine is mentioned only in passing.", "C": "The text says the field applies knowledge to prevent diseases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE001', 'HDSAT-RW-M33-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Epidemiology is the study and analysis of the distribution (who, when, and where), patterns and determinants of health and disease conditions in a defined population, and application of this knowledge to prevent diseases. It is a cornerstone of public health, and shapes policy decisions and evidence-based practice by identifying risk factors for disease and targets for preventive healthcare. Epidemiologists help with study design, collection, and statistical analysis of data, amend interpretation and dissemination of results (including peer review and occasional systematic review). Epidemiology has helped develop methodology used in clinical research, public health studies, and, to a lesser extent, basic research in the biological sciences. Major areas of epidemiological study include disease causation, transmission, outbreak investigation, disease surveillance, environmental epidemiology, forensic epidemiology, occupational epidemiology, screening, biomonitoring, and comparisons of treatment effects such as in clinical trials. Epidemiologists rely on other scientific disciplines like biology to better understand disease processes, statistics to make efficient use of the data and draw appropriate conclusions, social sciences to better understand proximate and distal causes, and engineering for exposure assessment.', 'Which quotation from the text most directly supports the claim that epidemiology studies populations?', '[{"id": "A", "text": "Major areas of epidemiological study include disease causation, transmission, outbreak investigation, and disease surveillance."}, {"id": "B", "text": "It is a cornerstone of public health, and shapes policy decisions and evidence-based practice."}, {"id": "C", "text": "Epidemiologists rely on other scientific disciplines like biology and statistics."}, {"id": "D", "text": "Epidemiology is the study and analysis of the distribution (who, when, and where), patterns and determinants of health and disease conditions in a defined population, and application of this knowledge to prevent diseases."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Epidemiology", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Epidemiology', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE001', 'D', ARRAY['D']::TEXT[], 'The correct quotation defines the field''s focus on a defined population.', '{"B": "This sentence describes the field''s role in public health.", "A": "This sentence lists areas of study.", "C": "This sentence describes relied-upon disciplines."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI002', 'HDSAT-RW-M33-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Sanitation refers to public health conditions related to clean drinking water and treatment and disposal of human excreta and sewage. Preventing human contact with feces is part of sanitation, as is hand washing with soap. Sanitation systems aim to protect human health by providing a clean environment that will stop the transmission of disease, especially through the fecal–oral route. For example, diarrhea, a main cause of malnutrition and stunted growth in children, can be reduced through adequate sanitation. There are many other diseases which are easily transmitted in communities that have low levels of sanitation, such as ascariasis (a type of intestinal worm infection or helminthiasis), cholera, hepatitis, polio, schistosomiasis, and trachoma, to name just a few. A range of sanitation technologies and approaches exists. Some examples are community-led total sanitation, container-based sanitation, ecological sanitation, emergency sanitation, environmental sanitation, onsite sanitation and sustainable sanitation. A sanitation system includes the capture, storage, transportation, treatment and disposal or reuse of human excreta and wastewater. Reuse activities within the sanitation system may focus on the nutrients, water, energy or organic matter contained in excreta and wastewater. This is referred to as the "sanitation value chain" or "sanitation economy".', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sanitation has no effect on disease transmission."}, {"id": "B", "text": "Sanitation protects health by managing excreta, sewage, and clean water to block disease transmission, especially fecal-oral routes."}, {"id": "C", "text": "Sanitation is concerned only with industrial waste."}, {"id": "D", "text": "Sanitation systems avoid treating wastewater."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sanitation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sanitation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI002', 'B', ARRAY['B']::TEXT[], 'The passage defines sanitation, explains its purpose, and describes technologies and the value chain.', '{"C": "The text defines sanitation through clean drinking water and treatment of excreta and sewage.", "A": "The text says systems aim to stop disease transmission.", "D": "The text says a system includes treatment and disposal or reuse."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF002', 'HDSAT-RW-M33-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Sanitation refers to public health conditions related to clean drinking water and treatment and disposal of human excreta and sewage. Preventing human contact with feces is part of sanitation, as is hand washing with soap. Sanitation systems aim to protect human health by providing a clean environment that will stop the transmission of disease, especially through the fecal–oral route. For example, diarrhea, a main cause of malnutrition and stunted growth in children, can be reduced through adequate sanitation. There are many other diseases which are easily transmitted in communities that have low levels of sanitation, such as ascariasis (a type of intestinal worm infection or helminthiasis), cholera, hepatitis, polio, schistosomiasis, and trachoma, to name just a few. A range of sanitation technologies and approaches exists. Some examples are community-led total sanitation, container-based sanitation, ecological sanitation, emergency sanitation, environmental sanitation, onsite sanitation and sustainable sanitation. A sanitation system includes the capture, storage, transportation, treatment and disposal or reuse of human excreta and wastewater. Reuse activities within the sanitation system may focus on the nutrients, water, energy or organic matter contained in excreta and wastewater. This is referred to as the "sanitation value chain" or "sanitation economy".
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF002', 'D', ARRAY['D']::TEXT[], 'Blocking fecal-oral transmission reduces diseases spread that way, including diarrhea.', '{"B": "The text says diarrhea can be reduced through adequate sanitation.", "A": "Sanitation prevents human contact with feces.", "C": "The text links diarrhea to malnutrition and stunted growth in children."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS002', 'HDSAT-RW-M33-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Sanitation refers to public health conditions related to clean drinking water and treatment and disposal of human excreta and sewage. Preventing human contact with feces is part of sanitation, as is hand washing with soap. Sanitation systems aim to protect human health by providing a clean environment that will stop the transmission of disease, especially through the fecal–oral route. For example, diarrhea, a main cause of malnutrition and stunted growth in children, can be reduced through adequate sanitation. There are many other diseases which are easily transmitted in communities that have low levels of sanitation, such as ascariasis (a type of intestinal worm infection or helminthiasis), cholera, hepatitis, polio, schistosomiasis, and trachoma, to name just a few. A range of sanitation technologies and approaches exists. Some examples are community-led total sanitation, container-based sanitation, ecological sanitation, emergency sanitation, environmental sanitation, onsite sanitation and sustainable sanitation. A sanitation system includes the capture, storage, transportation, treatment and disposal or reuse of human excreta and wastewater. Reuse activities within the sanitation system may focus on the nutrients, water, energy or organic matter contained in excreta and wastewater. This is referred to as the "sanitation value chain" or "sanitation economy".', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines sanitation, explains its health purpose, and describes technologies and the sanitation value chain."}, {"id": "B", "text": "It profiles a single sanitation worker."}, {"id": "C", "text": "It compares urban and rural sanitation in a table."}, {"id": "D", "text": "It argues that sanitation is unnecessary."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sanitation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sanitation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS002', 'A', ARRAY['A']::TEXT[], 'The passage moves from definition and purpose to systems and reuse.', '{"B": "No worker is profiled.", "C": "No table appears.", "D": "The text presents sanitation as protecting human health."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE002', 'HDSAT-RW-M33-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Sanitation refers to public health conditions related to clean drinking water and treatment and disposal of human excreta and sewage. Preventing human contact with feces is part of sanitation, as is hand washing with soap. Sanitation systems aim to protect human health by providing a clean environment that will stop the transmission of disease, especially through the fecal–oral route. For example, diarrhea, a main cause of malnutrition and stunted growth in children, can be reduced through adequate sanitation. There are many other diseases which are easily transmitted in communities that have low levels of sanitation, such as ascariasis (a type of intestinal worm infection or helminthiasis), cholera, hepatitis, polio, schistosomiasis, and trachoma, to name just a few. A range of sanitation technologies and approaches exists. Some examples are community-led total sanitation, container-based sanitation, ecological sanitation, emergency sanitation, environmental sanitation, onsite sanitation and sustainable sanitation. A sanitation system includes the capture, storage, transportation, treatment and disposal or reuse of human excreta and wastewater. Reuse activities within the sanitation system may focus on the nutrients, water, energy or organic matter contained in excreta and wastewater. This is referred to as the "sanitation value chain" or "sanitation economy".', 'Which quotation from the text most directly supports the claim that sanitation blocks disease transmission?', '[{"id": "A", "text": "Sanitation systems aim to protect human health by providing a clean environment that will stop the transmission of disease, especially through the fecal–oral route."}, {"id": "B", "text": "A range of sanitation technologies and approaches exists."}, {"id": "C", "text": "Preventing human contact with feces is part of sanitation, as is hand washing with soap."}, {"id": "D", "text": "Sanitation refers to public health conditions related to clean drinking water and treatment and disposal of human excreta and sewage."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sanitation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sanitation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE002', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly says sanitation stops disease transmission.', '{"D": "This sentence defines sanitation.", "C": "This sentence describes preventive practices.", "B": "This sentence notes varied technologies."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI003', 'HDSAT-RW-M33-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'An antibiotic is a type of antimicrobial substance which is active against bacteria. It is the most important type of antibacterial agent for fighting bacterial infections, and antibiotic medications are widely used in the treatment and prevention of such infections. They may either kill or inhibit the growth of bacteria. A limited number of antibiotics also possess antiprotozoal activity, but antibiotics are not effective against viruses or fungi. Sometimes, the term antibiotic—literally "opposing life", from the Greek roots ἀντι anti, "against" and βίος bios, "life"—is broadly used to refer to any substance used against microbes, but in normal medical usage antibiotics (such as penicillin) are those produced naturally (by one microorganism fighting another), whereas non-antibiotic antibacterials (such as sulfonamides and antiseptics) are fully synthetic. However, both classes have the same effect of killing or preventing the growth of microorganisms, and both are included in antimicrobial chemotherapy. "Antibacterials" include bactericides, bacteriostatics, antibacterial soaps, and chemical disinfectants, whereas antibiotics are an important class of antibacterials used more specifically in medicine and sometimes in livestock feed. == Early history == The earliest use of antibiotics was found in northern Sudan, where ancient Sudanese societies as early as 350–550 CE were systematically consuming antibiotics as part of their diet.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Antibiotics are substances active against bacteria that kill or inhibit them and are ineffective against viruses and fungi."}, {"id": "B", "text": "Antibiotics are synthetic chemicals only."}, {"id": "C", "text": "Antibiotics have never been used in livestock."}, {"id": "D", "text": "Antibiotics are effective against all viruses."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antibiotic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antibiotic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI003', 'A', ARRAY['A']::TEXT[], 'The passage defines antibiotics, explains their action, and distinguishes them from other antibacterials.', '{"D": "The text says antibiotics are not effective against viruses or fungi.", "B": "The text says antibiotics such as penicillin are produced naturally, while some antibacterials are synthetic.", "C": "The text says antibiotics are used in medicine and sometimes in livestock feed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF003', 'HDSAT-RW-M33-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'An antibiotic is a type of antimicrobial substance which is active against bacteria. It is the most important type of antibacterial agent for fighting bacterial infections, and antibiotic medications are widely used in the treatment and prevention of such infections. They may either kill or inhibit the growth of bacteria. A limited number of antibiotics also possess antiprotozoal activity, but antibiotics are not effective against viruses or fungi. Sometimes, the term antibiotic—literally "opposing life", from the Greek roots ἀντι anti, "against" and βίος bios, "life"—is broadly used to refer to any substance used against microbes, but in normal medical usage antibiotics (such as penicillin) are those produced naturally (by one microorganism fighting another), whereas non-antibiotic antibacterials (such as sulfonamides and antiseptics) are fully synthetic. However, both classes have the same effect of killing or preventing the growth of microorganisms, and both are included in antimicrobial chemotherapy. "Antibacterials" include bactericides, bacteriostatics, antibacterial soaps, and chemical disinfectants, whereas antibiotics are an important class of antibacterials used more specifically in medicine and sometimes in livestock feed. == Early history == The earliest use of antibiotics was found in northern Sudan, where ancient Sudanese societies as early as 350–550 CE were systematically consuming antibiotics as part of their diet.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF003', 'A', ARRAY['A']::TEXT[], 'Ineffectiveness against viruses means antibiotics would not help a viral infection.', '{"B": "The text explicitly says antibiotics are not effective against viruses.", "C": "Penicillin is an antibiotic, so it would not treat a virus.", "D": "The text does not recommend antibiotics for viral illness."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS003', 'HDSAT-RW-M33-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'An antibiotic is a type of antimicrobial substance which is active against bacteria. It is the most important type of antibacterial agent for fighting bacterial infections, and antibiotic medications are widely used in the treatment and prevention of such infections. They may either kill or inhibit the growth of bacteria. A limited number of antibiotics also possess antiprotozoal activity, but antibiotics are not effective against viruses or fungi. Sometimes, the term antibiotic—literally "opposing life", from the Greek roots ἀντι anti, "against" and βίος bios, "life"—is broadly used to refer to any substance used against microbes, but in normal medical usage antibiotics (such as penicillin) are those produced naturally (by one microorganism fighting another), whereas non-antibiotic antibacterials (such as sulfonamides and antiseptics) are fully synthetic. However, both classes have the same effect of killing or preventing the growth of microorganisms, and both are included in antimicrobial chemotherapy. "Antibacterials" include bactericides, bacteriostatics, antibacterial soaps, and chemical disinfectants, whereas antibiotics are an important class of antibacterials used more specifically in medicine and sometimes in livestock feed. == Early history == The earliest use of antibiotics was found in northern Sudan, where ancient Sudanese societies as early as 350–550 CE were systematically consuming antibiotics as part of their diet.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains how to prescribe antibiotics."}, {"id": "B", "text": "It compares antibiotics with vaccines."}, {"id": "C", "text": "It argues that antibiotics are always harmful."}, {"id": "D", "text": "It defines antibiotics and their action, distinguishes natural from synthetic antibacterials, and notes early historical use."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antibiotic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antibiotic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS003', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to classification and history.', '{"A": "No prescribing guidance is given.", "B": "Vaccines are not mentioned.", "C": "The text describes antibiotics as important for fighting bacterial infections."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE003', 'HDSAT-RW-M33-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'An antibiotic is a type of antimicrobial substance which is active against bacteria. It is the most important type of antibacterial agent for fighting bacterial infections, and antibiotic medications are widely used in the treatment and prevention of such infections. They may either kill or inhibit the growth of bacteria. A limited number of antibiotics also possess antiprotozoal activity, but antibiotics are not effective against viruses or fungi. Sometimes, the term antibiotic—literally "opposing life", from the Greek roots ἀντι anti, "against" and βίος bios, "life"—is broadly used to refer to any substance used against microbes, but in normal medical usage antibiotics (such as penicillin) are those produced naturally (by one microorganism fighting another), whereas non-antibiotic antibacterials (such as sulfonamides and antiseptics) are fully synthetic. However, both classes have the same effect of killing or preventing the growth of microorganisms, and both are included in antimicrobial chemotherapy. "Antibacterials" include bactericides, bacteriostatics, antibacterial soaps, and chemical disinfectants, whereas antibiotics are an important class of antibacterials used more specifically in medicine and sometimes in livestock feed. == Early history == The earliest use of antibiotics was found in northern Sudan, where ancient Sudanese societies as early as 350–550 CE were systematically consuming antibiotics as part of their diet.', 'Which quotation from the text most directly supports the claim that antibiotics target bacteria?', '[{"id": "A", "text": "Antibiotic medications are widely used in the treatment and prevention of such infections."}, {"id": "B", "text": "A limited number of antibiotics also possess antiprotozoal activity."}, {"id": "C", "text": "Antibiotics are not effective against viruses or fungi."}, {"id": "D", "text": "An antibiotic is a type of antimicrobial substance which is active against bacteria."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Antibiotic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Antibiotic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE003', 'D', ARRAY['D']::TEXT[], 'The correct quotation defines antibiotics as active against bacteria.', '{"A": "This sentence describes medical use.", "B": "This sentence notes a limited additional activity.", "C": "This sentence states what antibiotics do not affect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI004', 'HDSAT-RW-M33-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Maternal health is the health of women during pregnancy, childbirth, and the postpartum period. In most cases, maternal health encompasses the health care dimensions of family planning, and preconception, prenatal, and postnatal care in order to ensure a positive and fulfilling experience. In other cases, maternal health can reduce maternal morbidity and mortality. Maternal health revolves around the health and wellness of pregnant individuals, particularly when they are pregnant, at the time they give birth, and during child-raising. WHO has indicated that even though motherhood has been considered as a fulfilling natural experience that is emotional to the mother, a high percentage of women develop health problems, sometimes resulting in death. Because of this, there is a need to invest in the health of women. The investment can be achieved in different ways, among the main ones being subsidizing the healthcare cost, education on maternal health, encouraging effective family planning, and checking up on the health of individuals who have given birth. Maternal morbidity and mortality particularly affects women of color and women living in low and lower-middle income countries. == Maternal morbidity and mortality == WHO estimates that about 295,000 maternal deaths occurred in 2017. The causes of these maternal deaths range from severe bleeding to obstructed labour, all of which have highly effective interventions.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Maternal health requires no family planning."}, {"id": "B", "text": "Maternal health concerns only childbirth itself."}, {"id": "C", "text": "Maternal health concerns women''s health during pregnancy, birth, and postpartum, and requires investment to reduce preventable deaths."}, {"id": "D", "text": "Maternal mortality affects only wealthy countries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Maternal health", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Maternal_health', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI004', 'C', ARRAY['C']::TEXT[], 'The passage defines maternal health, describes its scope, and discusses mortality and interventions.', '{"B": "The text covers pregnancy, childbirth, and the postpartum period.", "D": "The text says it particularly affects women in low and lower-middle income countries.", "A": "The text includes family planning and preconception care."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF004', 'HDSAT-RW-M33-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Maternal health is the health of women during pregnancy, childbirth, and the postpartum period. In most cases, maternal health encompasses the health care dimensions of family planning, and preconception, prenatal, and postnatal care in order to ensure a positive and fulfilling experience. In other cases, maternal health can reduce maternal morbidity and mortality. Maternal health revolves around the health and wellness of pregnant individuals, particularly when they are pregnant, at the time they give birth, and during child-raising. WHO has indicated that even though motherhood has been considered as a fulfilling natural experience that is emotional to the mother, a high percentage of women develop health problems, sometimes resulting in death. Because of this, there is a need to invest in the health of women. The investment can be achieved in different ways, among the main ones being subsidizing the healthcare cost, education on maternal health, encouraging effective family planning, and checking up on the health of individuals who have given birth. Maternal morbidity and mortality particularly affects women of color and women living in low and lower-middle income countries. == Maternal morbidity and mortality == WHO estimates that about 295,000 maternal deaths occurred in 2017. The causes of these maternal deaths range from severe bleeding to obstructed labour, all of which have highly effective interventions.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF004', 'A', ARRAY['A']::TEXT[], 'If the causes are treatable, better access to treatment would lower deaths.', '{"C": "Effective interventions for the causes mean treatment can prevent deaths.", "D": "The text presents interventions as effective.", "B": "The text calls for investment precisely because care can improve outcomes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS004', 'HDSAT-RW-M33-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Maternal health is the health of women during pregnancy, childbirth, and the postpartum period. In most cases, maternal health encompasses the health care dimensions of family planning, and preconception, prenatal, and postnatal care in order to ensure a positive and fulfilling experience. In other cases, maternal health can reduce maternal morbidity and mortality. Maternal health revolves around the health and wellness of pregnant individuals, particularly when they are pregnant, at the time they give birth, and during child-raising. WHO has indicated that even though motherhood has been considered as a fulfilling natural experience that is emotional to the mother, a high percentage of women develop health problems, sometimes resulting in death. Because of this, there is a need to invest in the health of women. The investment can be achieved in different ways, among the main ones being subsidizing the healthcare cost, education on maternal health, encouraging effective family planning, and checking up on the health of individuals who have given birth. Maternal morbidity and mortality particularly affects women of color and women living in low and lower-middle income countries. == Maternal morbidity and mortality == WHO estimates that about 295,000 maternal deaths occurred in 2017. The causes of these maternal deaths range from severe bleeding to obstructed labour, all of which have highly effective interventions.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles a single mother''s pregnancy."}, {"id": "B", "text": "It defines maternal health, describes its components and disparities, and discusses mortality and interventions."}, {"id": "C", "text": "It argues that maternal health needs no investment."}, {"id": "D", "text": "It compares maternal health in two hospitals."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Maternal health", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Maternal_health', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS004', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition and scope to burden and solutions.', '{"A": "No individual case is profiled.", "D": "No hospital comparison is made.", "C": "The text says there is a need to invest in women''s health."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE004', 'HDSAT-RW-M33-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Maternal health is the health of women during pregnancy, childbirth, and the postpartum period. In most cases, maternal health encompasses the health care dimensions of family planning, and preconception, prenatal, and postnatal care in order to ensure a positive and fulfilling experience. In other cases, maternal health can reduce maternal morbidity and mortality. Maternal health revolves around the health and wellness of pregnant individuals, particularly when they are pregnant, at the time they give birth, and during child-raising. WHO has indicated that even though motherhood has been considered as a fulfilling natural experience that is emotional to the mother, a high percentage of women develop health problems, sometimes resulting in death. Because of this, there is a need to invest in the health of women. The investment can be achieved in different ways, among the main ones being subsidizing the healthcare cost, education on maternal health, encouraging effective family planning, and checking up on the health of individuals who have given birth. Maternal morbidity and mortality particularly affects women of color and women living in low and lower-middle income countries. == Maternal morbidity and mortality == WHO estimates that about 295,000 maternal deaths occurred in 2017. The causes of these maternal deaths range from severe bleeding to obstructed labour, all of which have highly effective interventions.', 'Which quotation from the text most directly supports the claim that maternal deaths are preventable?', '[{"id": "A", "text": "Maternal health is the health of women during pregnancy, childbirth, and the postpartum period."}, {"id": "B", "text": "The causes of these maternal deaths range from severe bleeding to obstructed labour, all of which have highly effective interventions."}, {"id": "C", "text": "Maternal morbidity and mortality particularly affects women of color and women living in low and lower-middle income countries."}, {"id": "D", "text": "WHO estimates that about 295,000 maternal deaths occurred in 2017."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Maternal health", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Maternal_health', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE004', 'B', ARRAY['B']::TEXT[], 'The correct quotation says the causes have highly effective interventions.', '{"A": "This sentence defines maternal health.", "D": "This sentence gives a mortality estimate.", "C": "This sentence describes disparities."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI005', 'HDSAT-RW-M33-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Nutrition is the biochemical and physiological process by which an organism uses food and water to support its life. The intake of these substances provides organisms with nutrients (divided into macro- and micro-) which can be metabolized to create energy and chemical structures; too much or too little of an essential nutrient can cause malnutrition. Nutritional science, the study of nutrition as a hard science, typically emphasizes human nutrition. The type of organism determines what nutrients it needs and how it obtains them. Organisms obtain nutrients by consuming organic matter, consuming inorganic matter, absorbing light, or some combination of these. Some can produce nutrients internally by consuming basic elements, while others must consume other organisms to obtain pre-existing nutrients. All forms of life require carbon, energy, and water as well as various other molecules. Animals require complex nutrients such as carbohydrates, lipids, and proteins, obtaining them by consuming other organisms. Humans have developed agriculture and cooking to replace foraging and advance human nutrition. Plants acquire nutrients through the soil and the atmosphere. Fungi absorb nutrients around them by breaking them down and absorbing them through the mycelium. == History == Scientific analysis of food and nutrients began during the chemical revolution in the late 18th century.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Too much of a nutrient is always harmless."}, {"id": "B", "text": "Nutrition applies only to animals."}, {"id": "C", "text": "Nutrients are needed only for energy."}, {"id": "D", "text": "Nutrition is how organisms obtain and use nutrients, and imbalances in essential nutrients cause malnutrition."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nutrition", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nutrition', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI005', 'D', ARRAY['D']::TEXT[], 'The passage defines nutrition, explains nutrient acquisition across organisms, and describes malnutrition.', '{"B": "The text discusses plants, fungi, and animals obtaining nutrients.", "C": "The text says nutrients are metabolized to create energy and chemical structures.", "A": "The text says too much or too little of an essential nutrient can cause malnutrition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
