INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF005', 'B', ARRAY['B']::TEXT[], 'The passage states that both too much and too little cause malnutrition, implying balance.', '{"A": "Both deficiency and excess cause harm, so balance matters.", "D": "Excess can cause malnutrition.", "C": "Nutrients are required for energy and structure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS005', 'HDSAT-RW-M33-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Nutrition is the biochemical and physiological process by which an organism uses food and water to support its life. The intake of these substances provides organisms with nutrients (divided into macro- and micro-) which can be metabolized to create energy and chemical structures; too much or too little of an essential nutrient can cause malnutrition. Nutritional science, the study of nutrition as a hard science, typically emphasizes human nutrition. The type of organism determines what nutrients it needs and how it obtains them. Organisms obtain nutrients by consuming organic matter, consuming inorganic matter, absorbing light, or some combination of these. Some can produce nutrients internally by consuming basic elements, while others must consume other organisms to obtain pre-existing nutrients. All forms of life require carbon, energy, and water as well as various other molecules. Animals require complex nutrients such as carbohydrates, lipids, and proteins, obtaining them by consuming other organisms. Humans have developed agriculture and cooking to replace foraging and advance human nutrition. Plants acquire nutrients through the soil and the atmosphere. Fungi absorb nutrients around them by breaking them down and absorbing them through the mycelium. == History == Scientific analysis of food and nutrients began during the chemical revolution in the late 18th century.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that cooking is harmful."}, {"id": "B", "text": "It lists calorie counts for common foods."}, {"id": "C", "text": "It compares human and plant digestion in detail."}, {"id": "D", "text": "It defines nutrition, explains how different organisms obtain nutrients, and notes the history of nutritional science."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nutrition", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nutrition', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS005', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition and nutrient types to acquisition and history.', '{"B": "No calorie table appears.", "C": "Plant and fungal acquisition are described briefly, not compared in detail.", "A": "The text says humans developed cooking to advance nutrition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE005', 'HDSAT-RW-M33-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Nutrition is the biochemical and physiological process by which an organism uses food and water to support its life. The intake of these substances provides organisms with nutrients (divided into macro- and micro-) which can be metabolized to create energy and chemical structures; too much or too little of an essential nutrient can cause malnutrition. Nutritional science, the study of nutrition as a hard science, typically emphasizes human nutrition. The type of organism determines what nutrients it needs and how it obtains them. Organisms obtain nutrients by consuming organic matter, consuming inorganic matter, absorbing light, or some combination of these. Some can produce nutrients internally by consuming basic elements, while others must consume other organisms to obtain pre-existing nutrients. All forms of life require carbon, energy, and water as well as various other molecules. Animals require complex nutrients such as carbohydrates, lipids, and proteins, obtaining them by consuming other organisms. Humans have developed agriculture and cooking to replace foraging and advance human nutrition. Plants acquire nutrients through the soil and the atmosphere. Fungi absorb nutrients around them by breaking them down and absorbing them through the mycelium. == History == Scientific analysis of food and nutrients began during the chemical revolution in the late 18th century.', 'Which quotation from the text most directly supports the claim that nutrition supports life processes?', '[{"id": "A", "text": "All forms of life require carbon, energy, and water as well as various other molecules."}, {"id": "B", "text": "The type of organism determines what nutrients it needs and how it obtains them."}, {"id": "C", "text": "Nutrition is the biochemical and physiological process by which an organism uses food and water to support its life."}, {"id": "D", "text": "The intake of these substances provides organisms with nutrients which can be metabolized to create energy and chemical structures."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Nutrition", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Nutrition', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE005', 'C', ARRAY['C']::TEXT[], 'The correct quotation defines nutrition as the process of using food and water to support life.', '{"D": "This sentence describes nutrient metabolism.", "B": "This sentence describes variation among organisms.", "A": "This sentence lists requirements shared by life."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI006', 'HDSAT-RW-M33-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Smoking cessation, usually called quitting smoking or stopping smoking, is the process of discontinuing tobacco smoking. Tobacco smoke contains nicotine, which is addictive and can cause dependence. As a result, nicotine withdrawal often makes the process of quitting difficult. Smoking is the leading cause of preventable death and a global public health concern. Tobacco use leads most commonly to diseases affecting the heart and lungs, with smoking being a major risk factor for heart attacks, strokes, chronic obstructive pulmonary disease (COPD), idiopathic pulmonary fibrosis (IPF), emphysema, and various types and subtypes of cancers (particularly lung cancer, cancers of the oropharynx, larynx, and mouth, esophageal and pancreatic cancer). Smoking cessation significantly reduces the risk of dying from smoking-related diseases. The risk of heart attack in a smoker decreases by 50% after one year of cessation. Similarly, the risk of lung cancer decreases by 50% in 10 years of cessation. From 2001 to 2010, about 70% of smokers in the United States expressed a desire to quit smoking, and 50% reported having attempted to do so in the past year. Many strategies can be used for smoking cessation, including abruptly quitting without assistance ("cold turkey"), cutting down then quitting, behavioral counseling, and medications such as bupropion, cytisine, nicotine replacement therapy, or varenicline.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Nicotine withdrawal makes quitting easier."}, {"id": "B", "text": "Quitting smoking is difficult because of nicotine addiction but sharply reduces the risk of smoking-related disease."}, {"id": "C", "text": "Quitting smoking has no health benefits."}, {"id": "D", "text": "Smoking is a minor cause of preventable death."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Smoking cessation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Smoking_cessation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI006', 'B', ARRAY['B']::TEXT[], 'The passage defines cessation, describes smoking''s harms and addiction, and explains benefits and strategies.', '{"C": "The text says cessation significantly reduces the risk of dying from smoking-related diseases.", "D": "The text calls smoking the leading cause of preventable death.", "A": "The text says withdrawal often makes quitting difficult."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF006', 'HDSAT-RW-M33-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Smoking cessation, usually called quitting smoking or stopping smoking, is the process of discontinuing tobacco smoking. Tobacco smoke contains nicotine, which is addictive and can cause dependence. As a result, nicotine withdrawal often makes the process of quitting difficult. Smoking is the leading cause of preventable death and a global public health concern. Tobacco use leads most commonly to diseases affecting the heart and lungs, with smoking being a major risk factor for heart attacks, strokes, chronic obstructive pulmonary disease (COPD), idiopathic pulmonary fibrosis (IPF), emphysema, and various types and subtypes of cancers (particularly lung cancer, cancers of the oropharynx, larynx, and mouth, esophageal and pancreatic cancer). Smoking cessation significantly reduces the risk of dying from smoking-related diseases. The risk of heart attack in a smoker decreases by 50% after one year of cessation. Similarly, the risk of lung cancer decreases by 50% in 10 years of cessation. From 2001 to 2010, about 70% of smokers in the United States expressed a desire to quit smoking, and 50% reported having attempted to do so in the past year. Many strategies can be used for smoking cessation, including abruptly quitting without assistance ("cold turkey"), cutting down then quitting, behavioral counseling, and medications such as bupropion, cytisine, nicotine replacement therapy, or varenicline.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF006', 'D', ARRAY['D']::TEXT[], 'The one-year halving of heart attack risk demonstrates a relatively rapid benefit.', '{"C": "A halved risk after one year shows rapid cardiovascular benefit.", "B": "The text describes a benefit within one year.", "A": "The text says the risk decreases, not increases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS006', 'HDSAT-RW-M33-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Smoking cessation, usually called quitting smoking or stopping smoking, is the process of discontinuing tobacco smoking. Tobacco smoke contains nicotine, which is addictive and can cause dependence. As a result, nicotine withdrawal often makes the process of quitting difficult. Smoking is the leading cause of preventable death and a global public health concern. Tobacco use leads most commonly to diseases affecting the heart and lungs, with smoking being a major risk factor for heart attacks, strokes, chronic obstructive pulmonary disease (COPD), idiopathic pulmonary fibrosis (IPF), emphysema, and various types and subtypes of cancers (particularly lung cancer, cancers of the oropharynx, larynx, and mouth, esophageal and pancreatic cancer). Smoking cessation significantly reduces the risk of dying from smoking-related diseases. The risk of heart attack in a smoker decreases by 50% after one year of cessation. Similarly, the risk of lung cancer decreases by 50% in 10 years of cessation. From 2001 to 2010, about 70% of smokers in the United States expressed a desire to quit smoking, and 50% reported having attempted to do so in the past year. Many strategies can be used for smoking cessation, including abruptly quitting without assistance ("cold turkey"), cutting down then quitting, behavioral counseling, and medications such as bupropion, cytisine, nicotine replacement therapy, or varenicline.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares smoking with alcohol use."}, {"id": "B", "text": "It defines cessation, explains nicotine addiction and smoking''s harms, and describes benefits and strategies."}, {"id": "C", "text": "It profiles a single former smoker."}, {"id": "D", "text": "It argues that cessation programs are ineffective."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Smoking cessation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Smoking_cessation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS006', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition and addiction to health effects and quitting methods.', '{"C": "No individual is profiled.", "A": "Alcohol is not discussed.", "D": "The text lists multiple effective strategies and benefits."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE006', 'HDSAT-RW-M33-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Smoking cessation, usually called quitting smoking or stopping smoking, is the process of discontinuing tobacco smoking. Tobacco smoke contains nicotine, which is addictive and can cause dependence. As a result, nicotine withdrawal often makes the process of quitting difficult. Smoking is the leading cause of preventable death and a global public health concern. Tobacco use leads most commonly to diseases affecting the heart and lungs, with smoking being a major risk factor for heart attacks, strokes, chronic obstructive pulmonary disease (COPD), idiopathic pulmonary fibrosis (IPF), emphysema, and various types and subtypes of cancers (particularly lung cancer, cancers of the oropharynx, larynx, and mouth, esophageal and pancreatic cancer). Smoking cessation significantly reduces the risk of dying from smoking-related diseases. The risk of heart attack in a smoker decreases by 50% after one year of cessation. Similarly, the risk of lung cancer decreases by 50% in 10 years of cessation. From 2001 to 2010, about 70% of smokers in the United States expressed a desire to quit smoking, and 50% reported having attempted to do so in the past year. Many strategies can be used for smoking cessation, including abruptly quitting without assistance ("cold turkey"), cutting down then quitting, behavioral counseling, and medications such as bupropion, cytisine, nicotine replacement therapy, or varenicline.', 'Which quotation from the text most directly supports the claim that quitting reduces disease risk?', '[{"id": "A", "text": "Smoking cessation is the process of discontinuing tobacco smoking."}, {"id": "B", "text": "Smoking is the leading cause of preventable death and a global public health concern."}, {"id": "C", "text": "Smoking cessation significantly reduces the risk of dying from smoking-related diseases."}, {"id": "D", "text": "Tobacco smoke contains nicotine, which is addictive and can cause dependence."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Smoking cessation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Smoking_cessation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE006', 'C', ARRAY['C']::TEXT[], 'The correct quotation states that cessation reduces mortality risk from smoking-related diseases.', '{"A": "This sentence defines cessation.", "D": "This sentence describes nicotine addiction.", "B": "This sentence describes smoking''s overall harm."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI007', 'HDSAT-RW-M33-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Health equity concerns only genetic factors."}, {"id": "B", "text": "Health equity means fair health outcomes achieved through need-based allocation of resources, not merely equal access."}, {"id": "C", "text": "Health equity means providing identical services to everyone."}, {"id": "D", "text": "Health equity is unrelated to social determinants."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Health equity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Health_equity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI007', 'B', ARRAY['B']::TEXT[], 'The passage defines health equity, explains its determinants, and distinguishes it from equal access.', '{"C": "The text says resources must be allocated on a need-based principle.", "D": "The text distinguishes health equity from formal equal opportunity.", "A": "The text ties disparities to wealth, power, and prestige."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF007', 'HDSAT-RW-M33-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF007', 'A', ARRAY['A']::TEXT[], 'Uniform services ignore unequal needs, so they may leave disparities intact.', '{"D": "Equal services do not account for differing needs and disadvantages.", "C": "The text says health equity is distinct from simply equal access.", "B": "The text calls for need-based allocation, not that equality worsens disparities."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS007', 'HDSAT-RW-M33-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that health is not a human right."}, {"id": "B", "text": "It defines health equity, explains its social determinants, and distinguishes it from equal access."}, {"id": "C", "text": "It profiles a single health clinic."}, {"id": "D", "text": "It compares health systems in two countries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Health equity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Health_equity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-TS007', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition to determinants and a key distinction.', '{"C": "No clinic is profiled.", "D": "No country comparison is made.", "A": "The text calls health a basic human right."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE007', 'HDSAT-RW-M33-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Health equity is social equity in health. Disparities in health outcomes can be related to differences in access to social determinants of health, specifically from wealth, power and prestige. Individuals who have consistently been deprived of these three determinants are significantly disadvantaged from health inequities, and face worse health outcomes than those who are able to access certain resources. This is especially important in areas with increased diversity across social, ethnic, and racial groups, as underrepresentation in healthcare systems is a global issue. In order to achieve health equity, resources must be allocated based on an individual need-based principle. Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care. Health equity is also connected with Scientific Equity, which describes the scientific methods by which to achieve Health Equity. According to the World Health Organization, "Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity". The quality of health and how health is distributed among economic and social status in a society can provide insight into the level of development within that society. Health is a basic human right and human need, and all human rights are interconnected. Thus, health must be discussed along with all other basic human rights.', 'Which quotation from the text most directly supports the claim that health equity differs from equal access?', '[{"id": "A", "text": "Health equity is distinct from formal equal opportunity, such as simply providing every individual with equal access to health care."}, {"id": "B", "text": "In order to achieve health equity, resources must be allocated based on an individual need-based principle."}, {"id": "C", "text": "Health equity is social equity in health."}, {"id": "D", "text": "Disparities in health outcomes can be related to differences in access to social determinants of health."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Health equity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Health_equity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE007', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly separates health equity from equal access.', '{"C": "This sentence defines health equity.", "D": "This sentence describes determinants.", "B": "This sentence describes need-based allocation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI008', 'HDSAT-RW-M33-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In epidemiology, an outbreak is a sudden increase in occurrences of a disease when cases are in excess of normal expectancy for the location or season. It may affect a small and localized group or impact upon thousands of people across an entire continent. The number of cases varies according to the disease-causing agent, and the size and type of previous and existing exposure to the agent. Outbreaks include many epidemics, which is a term normally only used for infectious diseases, as well as diseases with an environmental origin, such as a water or foodborne disease. They may affect a region in a country or a group of countries. Pandemics are near-global disease outbreaks when multiple and various countries around the Earth are soon infected. == Definition == The terms "outbreak" and "epidemic" have often been used interchangeably. Researchers Manfred S. Green and colleagues propose that the latter term be restricted to larger events, pointing out that Chambers Concise Dictionary and Stedman''s Medical Dictionary acknowledge this distinction. == Outbreak investigation == When investigating disease outbreaks, the epidemiology profession has developed a number of widely accepted steps.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "An outbreak is any single case of a disease."}, {"id": "B", "text": "An outbreak is a rise in disease cases above normal expectancy, ranging from local clusters to pandemics."}, {"id": "C", "text": "Outbreaks affect only one continent."}, {"id": "D", "text": "Pandemics are smaller than local outbreaks."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Disease outbreak", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Disease_outbreak', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI008', 'B', ARRAY['B']::TEXT[], 'The passage defines outbreaks, describes their scale, and distinguishes related terms.', '{"A": "The text defines an outbreak as cases in excess of normal expectancy.", "C": "The text says it may affect a small group or thousands across a continent.", "D": "The text describes pandemics as near-global outbreaks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF008', 'HDSAT-RW-M33-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In epidemiology, an outbreak is a sudden increase in occurrences of a disease when cases are in excess of normal expectancy for the location or season. It may affect a small and localized group or impact upon thousands of people across an entire continent. The number of cases varies according to the disease-causing agent, and the size and type of previous and existing exposure to the agent. Outbreaks include many epidemics, which is a term normally only used for infectious diseases, as well as diseases with an environmental origin, such as a water or foodborne disease. They may affect a region in a country or a group of countries. Pandemics are near-global disease outbreaks when multiple and various countries around the Earth are soon infected. == Definition == The terms "outbreak" and "epidemic" have often been used interchangeably. Researchers Manfred S. Green and colleagues propose that the latter term be restricted to larger events, pointing out that Chambers Concise Dictionary and Stedman''s Medical Dictionary acknowledge this distinction. == Outbreak investigation == When investigating disease outbreaks, the epidemiology profession has developed a number of widely accepted steps.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF008', 'D', ARRAY['D']::TEXT[], 'Since the baseline differs by place and season, the same count may exceed one baseline and not another.', '{"A": "Expectancy depends on place and season, so the threshold varies.", "B": "A pandemic requires near-global spread.", "C": "The definition explicitly refers to location and season."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-TS008', 'HDSAT-RW-M33-TS008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'In epidemiology, an outbreak is a sudden increase in occurrences of a disease when cases are in excess of normal expectancy for the location or season. It may affect a small and localized group or impact upon thousands of people across an entire continent. The number of cases varies according to the disease-causing agent, and the size and type of previous and existing exposure to the agent. Outbreaks include many epidemics, which is a term normally only used for infectious diseases, as well as diseases with an environmental origin, such as a water or foodborne disease. They may affect a region in a country or a group of countries. Pandemics are near-global disease outbreaks when multiple and various countries around the Earth are soon infected. == Definition == The terms "outbreak" and "epidemic" have often been used interchangeably. Researchers Manfred S. Green and colleagues propose that the latter term be restricted to larger events, pointing out that Chambers Concise Dictionary and Stedman''s Medical Dictionary acknowledge this distinction. == Outbreak investigation == When investigating disease outbreaks, the epidemiology profession has developed a number of widely accepted steps.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the investigation of a single outbreak."}, {"id": "B", "text": "It argues that outbreaks cannot be defined."}, {"id": "C", "text": "It compares infectious and chronic diseases."}, {"id": "D", "text": "It defines an outbreak, describes its possible scale