INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CE008', 'HDSAT-RW-M33-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'In epidemiology, an outbreak is a sudden increase in occurrences of a disease when cases are in excess of normal expectancy for the location or season. It may affect a small and localized group or impact upon thousands of people across an entire continent. The number of cases varies according to the disease-causing agent, and the size and type of previous and existing exposure to the agent. Outbreaks include many epidemics, which is a term normally only used for infectious diseases, as well as diseases with an environmental origin, such as a water or foodborne disease. They may affect a region in a country or a group of countries. Pandemics are near-global disease outbreaks when multiple and various countries around the Earth are soon infected. == Definition == The terms "outbreak" and "epidemic" have often been used interchangeably. Researchers Manfred S. Green and colleagues propose that the latter term be restricted to larger events, pointing out that Chambers Concise Dictionary and Stedman''s Medical Dictionary acknowledge this distinction. == Outbreak investigation == When investigating disease outbreaks, the epidemiology profession has developed a number of widely accepted steps.', 'Which quotation from the text most directly supports the claim that outbreaks vary greatly in scale?', '[{"id": "A", "text": "Pandemics are near-global disease outbreaks when multiple and various countries around the Earth are soon infected."}, {"id": "B", "text": "In epidemiology, an outbreak is a sudden increase in occurrences of a disease when cases are in excess of normal expectancy."}, {"id": "C", "text": "It may affect a small and localized group or impact upon thousands of people across an entire continent."}, {"id": "D", "text": "Outbreaks include many epidemics, which is a term normally only used for infectious diseases."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Disease outbreak", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Disease_outbreak', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CE008', 'C', ARRAY['C']::TEXT[], 'The correct quotation contrasts a small local group with thousands across a continent.', '{"B": "This sentence defines an outbreak.", "D": "This sentence discusses epidemics.", "A": "This sentence defines a pandemic."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI009', 'HDSAT-RW-M33-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Water purification is the process of removing undesirable chemicals, biological contaminants, suspended solids, and gases from water. The goal is to produce water that is fit for specific purposes. Most water is purified and disinfected for human consumption (drinking water), but water purification may also be carried out for a variety of other purposes, including medical, pharmacological, chemical, and industrial applications. The history of water purification includes a wide variety of methods. The methods used include physical processes such as filtration, sedimentation, and distillation; biological processes such as slow sand filters or biologically active carbon; chemical processes such as flocculation and chlorination; and the use of electromagnetic radiation such as ultraviolet light. Water purification can reduce the concentration of particulate matter including suspended particles, parasites, bacteria, algae, viruses, and fungi as well as reduce the concentration of a range of dissolved and particulate matter. The standards for drinking water quality are typically set by governments or by international standards. These standards usually include minimum and maximum concentrations of contaminants, depending on the intended use of the water. A visual inspection cannot determine if water is of appropriate quality.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Purification uses only chemical methods."}, {"id": "B", "text": "Water purification removes contaminants using physical, biological, chemical, and radiation methods to make water fit for specific uses."}, {"id": "C", "text": "Water purification adds contaminants to water."}, {"id": "D", "text": "Drinking water standards are never set by governments."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Water purification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Water_purification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI009', 'B', ARRAY['B']::TEXT[], 'The passage defines purification, surveys its methods, and explains drinking water standards.', '{"C": "The text defines purification as removing undesirable substances.", "A": "The text lists filtration, sedimentation, distillation, biological filters, flocculation, chlorination, and UV light.", "D": "The text says standards are typically set by governments or international standards."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-INF009', 'HDSAT-RW-M33-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Water purification is the process of removing undesirable chemicals, biological contaminants, suspended solids, and gases from water. The goal is to produce water that is fit for specific purposes. Most water is purified and disinfected for human consumption (drinking water), but water purification may also be carried out for a variety of other purposes, including medical, pharmacological, chemical, and industrial applications. The history of water purification includes a wide variety of methods. The methods used include physical processes such as filtration, sedimentation, and distillation; biological processes such as slow sand filters or biologically active carbon; chemical processes such as flocculation and chlorination; and the use of electromagnetic radiation such as ultraviolet light. Water purification can reduce the concentration of particulate matter including suspended particles, parasites, bacteria, algae, viruses, and fungi as well as reduce the concentration of a range of dissolved and particulate matter. The standards for drinking water quality are typically set by governments or by international standards. These standards usually include minimum and maximum concentrations of contaminants, depending on the intended use of the water. A visual inspection cannot determine if water is of appropriate quality.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-INF009', 'D', ARRAY['D']::TEXT[], 'If appearance cannot establish quality, testing against standards is needed.', '{"B": "Quality standards set concentration limits that must be measured.", "C": "The text says visual inspection is insufficient.", "A": "Assessment requires checking contaminant concentrations."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
