INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M33-CI010', 'HDSAT-RW-M33-CI010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Mental health encompasses emotional, psychological, and social well-being, influencing cognition, perception, and behavior. Mental health plays a crucial role in an individual''s daily life when managing stress, engaging with others, and contributing to life overall. According to the World Health Organization (WHO), it is a "state of well-being in which the individual realizes their abilities, can cope with the normal stresses of life, can work productively and fruitfully, and can contribute to their community". It likewise determines how an individual handles stress, interpersonal relationships, and decision-making. Mental health includes subjective well-being, perceived self-efficacy, autonomy, competence, intergenerational dependence, and self-actualization of one''s intellectual and emotional potential, among others. From the perspectives of positive psychology or holism, mental health is thus not merely the absence of mental illness. Rather, it is a broader state of well-being that includes an individual''s ability to enjoy life and to create a balance between life activities and efforts to achieve psychological resilience. Cultural differences, personal philosophy, subjective assessments, and competing professional theories all affect how one defines "mental health".', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mental health has the same definition in every culture."}, {"id": "B", "text": "Mental health is a broad state of emotional, psychological, and social well-being, not merely the absence of mental illness."}, {"id": "C", "text": "Mental health is simply the absence of mental illness."}, {"id": "D", "text": "Mental health concerns only emotional well-being."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mental health", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mental_health', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M33-CI010', 'B', ARRAY['B']::TEXT[], 'The passage defines mental health, describes its components, and notes cultural variation.', '{"C": "The text says mental health is not merely the absence of mental illness.", "D": "The text includes emotional, psychological, and social well-being.", "A": "The text says cultural differences affect how mental health is defined."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
